/**
 * @event
 * @name scwin.btn_fileDownRelLaw_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fileDownRelLaw_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fileDownRelLaw_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fileDownRelLaw('' + dma_resultM.get("sprtRoomNo") + '','' + dma_resultM.get("attachSeq") + '','' + dma_resultM.get("attachFileNm") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20030.btn_fileDownRelLaw_onclick' }); }
};

