/**
 * @method
 * @name scwin.fileDownRelLaw
 * @author Inswave
 * @date 2026. 09. 29
 * @param roomNo ipt_attachSeq fileNm
 * @returns
 * @hidden N
*/
scwin.fileDownRelLaw = function (roomNo, ipt_attachSeq, fileNm) {
    /* sdd-asis-lifecycle:begin fileDownRelLaw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_sprtRoomNo', $('#attachForm')).val(roomNo);
    $('#ipt_attachSeq', $('#attachForm')).val(ipt_attachSeq);
    $('#ipt_attachFileNm', $('#attachForm')).val(fileNm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/uldods20030/uldods20030.xml");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile");
    $('#attachForm').submit();
    /* sdd-asis-lifecycle:end */
};
